        {
          "proposicao": "A avaliação quantitativa de risco aplicada a gasoduto é descrita como estimativa numérica do risco baseada no cálculo de frequências e consequências de um conjunto completo e representativo de cenários de acidentes credíveis.",
          "trechos": [
            "E96e58e9477a5b439:1393:2089"
          ],
          "condicoes": [
            "No contexto da norma britânica citada para gasodutos com perigos de acidente maior"
          ],
          "limites": [
            "Escopo voltado a gasodutos em terra e seu entorno, não especificamente a FPSOs",
            "Norma estrangeira não se converte automaticamente em requisito brasileiro"
          ]
        },
        {
          "proposicao": "O cálculo de avaliação de risco é apresentado em cinco passos, incluindo coleta de dados, previsão de frequência de falhas, previsão de consequências, cálculo do risco e avaliação de critérios.",
          "trechos": [
            "E96e58e9477a5b439:1393:2089",
            "E96e58e9477a5b439:2089:2387"
          ],
          "condicoes": [
            "Conforme a metodologia resumida da norma referida"
          ],
          "limites": [
            "O excerto está incompleto no quinto passo e não detalha critérios de aceitabilidade",
            "Aplicação imediata a FPSO exige cautela por diferença de contexto"
          ]
        },
        {
          "proposicao": "A modelagem de consequências mencionada inclui taxa de liberação, dispersão de vapores inflamáveis, radiação térmica e quantificação de efeitos sobre a população, articulando probabilidade e severidade no cálculo do risco individual e social.",
          "trechos": [
            "E96e58e9477a5b439:2089:2387"
          ],
          "condicoes": [
            "Para cenários de falhas considerados na avaliação quantitativa de risco"
          ],
          "limites": [
            "Foco em população no entorno de gasodutos, não em seleção de controles ou risco residual em operações de FPSO"
          ]
        }
